import{_ as d,l as n,o as a,c as i,v as o,p as s,x as r,d as l,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"舍入模式","description":"","frontmatter":{"title":"舍入模式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rounding-modes.md","filePath":"cs/rounding-modes.md","lastUpdated":1789023840000}'),h={name:"cs/rounding-modes.md"};function p(u,e,m,_,A,T){const t=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="舍入模式" tabindex="-1">舍入模式 <a class="header-anchor" href="#舍入模式" aria-label="Permalink to &quot;舍入模式&quot;">​</a></h1><div class="epigraph"><p>精确结果常常不在格子上；往哪一个可表示的邻居靠，必须先约定，否则同一算法换一台机器会换一批比特。</p><footer>—— 据 IEEE Std 754-2008；Knuth, The Art of Computer Programming, Vol. 2；Goldberg, 1991 整理</footer></div><p>上一课<a href="/cs/ieee-754">IEEE 754</a>钉死了 <code>binary32</code>/<code>binary64</code> 的位型，并点名默认 round-to-nearest-even。本课不重列偏置与隐藏位，也不从「实数逼近论」另起。缺口是：有限尾数上，加减乘除的<strong>精确数学结果</strong>往往落在两个可表示数之间。默认模式被点了名，还没有说清还有哪些模式、平局怎么破、有向舍入给谁用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>754 的格子不是 \\(\\mathbb{R}\\)。运算先产生理想结果，再映射回格子。缺口因此不是再切指数宽度，而是钉一套<strong>舍入属性</strong>：最近偶数、朝零、朝正无穷、朝负无穷，以及 2008 年写清的 ties-to-away。同一表达式、同一操作数，模式不同则结果比特可以不同；数值库与区间算术依赖「朝哪边」可重复。</p><p>本课只钉二进制格式上这几条。非规格化与 NaN 在精确结果落到零附近或无效时才成为主角，那是<a href="/cs/denormal-nan">下一课</a>。</p><h3 id="最近偶数不是「四舍五入」" tabindex="-1">最近偶数不是「四舍五入」 <a class="header-anchor" href="#最近偶数不是「四舍五入」" aria-label="Permalink to &quot;最近偶数不是「四舍五入」&quot;">​</a></h3><p>十进制四舍五入在 <code>.5</code> 处总是远离零，会引入单向偏差。754 的默认是：距离相等时选最低有效位为 \\(0\\) 的那个（偶数）。把学校里的四舍五入直接当成默认，统计上的均值会偏，也与硬件默认不符。</p><p><span class="marginnote">IEEE 754-2008 §4 把舍入属性写成独立于格式的条款。Knuth Vol. 2 §4.2 强调浮点算术是有限集上的运算，舍入是定义的一部分，不是事后修饰。Goldberg 用例子说明同一表达式换模式后差在哪一位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记理想结果为 \\(x\\)，可表示集为 \\(F\\)。最近：选 \\(F\\) 中距 \\(x\\) 最小者；平局时默认选偶数尾数（<code>roundTiesToEven</code>），或选幅值更大者（<code>roundTiesToAway</code>）。有向：<code>roundTowardZero</code> 取不比 \\(x\\) 更远离零的那个；<code>roundTowardPositive</code> / <code>roundTowardNegative</code> 分别不小于 / 不大于 \\(x\\)。不精确时置 inexact 旗标——旗标如何进陷阱，本课不接。</p>',11)),(a(),s(E,null,{default:r(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDEAL%5B%22%E7%90%86%E6%83%B3%E5%AE%9E%E7%BB%93%E6%9E%9C%22%5D%20--%3E%20MODE%5B%22%E7%BA%A6%E5%AE%9A%E8%88%8D%E5%85%A5%E5%B1%9E%E6%80%A7%22%5D%0A%20%20MODE%20--%3E%20GRID%5B%22%E6%A0%BC%E5%AD%90%E4%B8%8A%E7%9A%84%E9%82%BB%E5%B1%85%22%5D%0A%20%20GRID%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%9B%B6%E9%99%84%E8%BF%91%E4%B8%8E%20NaN%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>默认模式对大多数科学计算够用。区间算术需要有向舍入夹住真值；本课只承认这件事，不构造区间库。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>FMA 把乘加熔成一次舍入，与「先乘后加」两次舍入可以不同——上一课已承认。本课补的是：即便单次运算，模式也是 ABI 与控制寄存器的一部分。RISC-V 的 <code>frm</code> 选择模式；语言默认通常绑最近偶数。比较与哈希仍先问比的是比特还是数值：舍入改变的是产生哪些比特。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把十进制 754 的舍入另开一张表，不讨论随机舍入（stochastic rounding）作为训练技巧——那不是 754-2008 的强制属性。也不把误差界写成定理：Goldberg 的 ulp 讨论到能用为止，完整舍入误差分析不进主干。</p><p>后课默认：未声明时，二进制浮点舍入是 round-to-nearest-even；改变模式会改变结果比特。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>舍入把理想结果映回 754 格子；模式必须先约定。</li><li>默认最近偶数，平局选偶数尾数，不是十进制四舍五入。</li><li>有向舍入服务区间与定向误差；零附近的特殊值下一课再钉。</li><li>出处：IEEE 754-2008；Knuth, TAOCP Vol. 2；Goldberg, 1991。</li></ul>',8))])}const b=d(h,[["render",p]]);export{B as __pageData,b as default};
